import React from "react";
import Link from "next/link";
import {
  Image as ImageIcon,
  FileText,
  Code2,
  Type,
  Calculator,
  Share2,
  LayoutGrid,
  ArrowRight,
  LucideIcon,
} from "lucide-react";
import { CATEGORIES } from "@/data/categories";

const CATEGORY_ICONS: Record<string, LucideIcon> = {
  Image: ImageIcon,
  FileText: FileText,
  Code2: Code2,
  Type: Type,
  Calculator: Calculator,
  Share2: Share2,
  LayoutGrid: LayoutGrid,
};

export function CategoryPreview() {
  return (
    <section className="w-full bg-[#F7F8FC] py-12 md:py-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-7 gap-3 sm:gap-4">
          {CATEGORIES.map((category) => {
            const Icon = CATEGORY_ICONS[category.iconName] || LayoutGrid;
            return (
              <Link
                key={category.id}
                href={category.id === "more" ? "/tools" : `/categories/${category.slug}`}
                className="group flex flex-col items-center text-center p-5 bg-white rounded-2xl md:rounded-3xl border border-slate-200/70 shadow-sm hover:shadow-md hover:border-indigo-300 hover:-translate-y-1 transition-all duration-300"
              >
                {/* Category Icon Container */}
                <div
                  className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 bg-gradient-to-br ${category.bgGradient} ${category.iconColor} border border-slate-100 group-hover:scale-110 transition-transform duration-300`}
                >
                  <Icon className="w-7 h-7" />
                </div>

                {/* Title */}
                <h3 className="text-sm font-bold text-[#111936] group-hover:text-indigo-600 transition-colors mb-1">
                  {category.name}
                </h3>

                {/* Description */}
                <p className="text-[11px] text-[#52607A] line-clamp-2 leading-relaxed">
                  {category.description}
                </p>
              </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
}

export default CategoryPreview;
